def gen(rng):
    from collections import deque
    def build(order):
        vals = [order[0]]; L = [-1]; R = [-1]
        for v in order[1:]:
            u = 0
            while True:
                if v < vals[u]:
                    if L[u] == -1:
                        vals.append(v); L.append(-1); R.append(-1); L[u] = len(vals) - 1; break
                    u = L[u]
                else:
                    if R[u] == -1:
                        vals.append(v); L.append(-1); R.append(-1); R[u] = len(vals) - 1; break
                    u = R[u]
        return vals, L, R
    def ser(vals, L, R):
        out = []
        dq = deque([0])
        while dq:
            u = dq.popleft()
            if u == -1:
                out.append('null')
            else:
                out.append(str(vals[u])); dq.append(L[u]); dq.append(R[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)
    def balanced(sv):
        order = []
        dq = deque([(0, len(sv) - 1)])
        while dq:
            lo, hi = dq.popleft()
            if lo > hi:
                continue
            mid = (lo + hi) // 2
            order.append(sv[mid])
            dq.append((lo, mid - 1)); dq.append((mid + 1, hi))
        return order
    def test(order, v):
        vals, L, R = build(order)
        return ser(vals, L, R) + '\n' + str(v)
    tests = [test([4, 2, 7, 1, 3], 2), test([4, 2, 7, 1, 3], 5), test([5, 3, 8, 4, 6], 3),
