    tests.append(test(order, rng.choice(order)))
    tests.append(test(order, rng.choice(order[-100:])))
    tests.append(test(order, 10**7 + 0 if 10**7 not in order else 1))
    sv = sorted(rng.sample(range(1, 10**7 + 1), n))
    bo = balanced(sv)
    tests.append(test(bo, bo[0]))
    tests.append(test(bo, sv[n // 3]))
